ALTER TABLE `team_folder_members` MODIFY COLUMN `role` ENUM('ADMIN','ORGANIZER','EDITOR','COMMENTER','VIEWER') NOT NULL;
ALTER TABLE `organizations` ADD COLUMN `owner_id` CHAR(36) NULL;
ALTER TABLE `users` ADD COLUMN `status` ENUM('INVITED','ACTIVE','SUSPENDED','DEACTIVATED') NOT NULL DEFAULT 'ACTIVE', ADD COLUMN `avatar_url` VARCHAR(191) NULL, ADD COLUMN `last_login_at` DATETIME(3) NULL;
ALTER TABLE `team_folders` ADD COLUMN `allow_external_sharing` BOOLEAN NOT NULL DEFAULT true, ADD COLUMN `allow_viewer_downloads` BOOLEAN NOT NULL DEFAULT true, ADD COLUMN `archived_at` DATETIME(3) NULL;
UPDATE organizations o JOIN (SELECT org_id, SUBSTRING_INDEX(GROUP_CONCAT(id ORDER BY created_at ASC), ',', 1) AS owner_id FROM users WHERE role='ADMIN' GROUP BY org_id) x ON x.org_id=o.id SET o.owner_id=x.owner_id WHERE o.owner_id IS NULL;
ALTER TABLE `organizations` ADD CONSTRAINT `organizations_owner_id_fkey` FOREIGN KEY (`owner_id`) REFERENCES `users`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
CREATE INDEX `users_org_id_status_idx` ON `users`(`org_id`,`status`);
CREATE TABLE `groups` (`id` CHAR(36) NOT NULL, `org_id` CHAR(36) NOT NULL, `name` VARCHAR(191) NOT NULL, `description` TEXT NULL, `created_by_id` CHAR(36) NOT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `groups_org_id_name_key` (`org_id`,`name`), KEY `groups_org_id_idx` (`org_id`), CONSTRAINT `groups_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `groups_created_by_id_fkey` FOREIGN KEY (`created_by_id`) REFERENCES `users`(`id`) ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `group_members` (`id` CHAR(36) NOT NULL, `org_id` CHAR(36) NOT NULL, `group_id` CHAR(36) NOT NULL, `user_id` CHAR(36) NOT NULL, `role` ENUM('ADMIN','MEMBER') NOT NULL DEFAULT 'MEMBER', `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE KEY `group_members_group_id_user_id_key` (`group_id`,`user_id`), KEY `group_members_org_id_user_id_idx` (`org_id`,`user_id`), CONSTRAINT `group_members_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `group_members_group_id_fkey` FOREIGN KEY (`group_id`) REFERENCES `groups`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `group_members_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `folder_permissions` (`id` CHAR(36) NOT NULL, `org_id` CHAR(36) NOT NULL, `folder_id` CHAR(36) NOT NULL, `user_id` CHAR(36) NULL, `group_id` CHAR(36) NULL, `access` ENUM('NONE','VIEW','COMMENT','EDIT','ORGANIZE') NOT NULL DEFAULT 'VIEW', `hidden` BOOLEAN NOT NULL DEFAULT false, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), KEY `folder_permissions_org_id_folder_id_idx` (`org_id`,`folder_id`), KEY `folder_permissions_org_id_user_id_idx` (`org_id`,`user_id`), KEY `folder_permissions_org_id_group_id_idx` (`org_id`,`group_id`), CONSTRAINT `folder_permissions_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `folder_permissions_folder_id_fkey` FOREIGN KEY (`folder_id`) REFERENCES `folders`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `folder_permissions_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `folder_permissions_group_id_fkey` FOREIGN KEY (`group_id`) REFERENCES `groups`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `security_policies` (`id` CHAR(36) NOT NULL, `org_id` CHAR(36) NOT NULL, `require_mfa` BOOLEAN NOT NULL DEFAULT false, `allow_external_sharing` BOOLEAN NOT NULL DEFAULT true, `allow_public_links` BOOLEAN NOT NULL DEFAULT true, `max_share_days` INTEGER NULL, `max_upload_bytes` BIGINT NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `security_policies_org_id_key` (`org_id`), CONSTRAINT `security_policies_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `retention_policies` (`id` CHAR(36) NOT NULL, `org_id` CHAR(36) NOT NULL, `trash_days` INTEGER NOT NULL DEFAULT 30, `deleted_items_days` INTEGER NOT NULL DEFAULT 365, `version_limit` INTEGER NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE KEY `retention_policies_org_id_key` (`org_id`), CONSTRAINT `retention_policies_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `malware_scans` (`id` CHAR(36) NOT NULL, `org_id` CHAR(36) NOT NULL, `file_id` CHAR(36) NOT NULL, `status` ENUM('PENDING','CLEAN','INFECTED','FAILED') NOT NULL DEFAULT 'PENDING', `engine` VARCHAR(191) NULL, `signature` VARCHAR(191) NULL, `scanned_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), KEY `malware_scans_org_id_file_id_idx` (`org_id`,`file_id`), KEY `malware_scans_org_id_status_idx` (`org_id`,`status`), CONSTRAINT `malware_scans_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `malware_scans_file_id_fkey` FOREIGN KEY (`file_id`) REFERENCES `files`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `user_devices` (`id` CHAR(36) NOT NULL, `org_id` CHAR(36) NOT NULL, `user_id` CHAR(36) NOT NULL, `name` VARCHAR(191) NULL, `platform` VARCHAR(191) NULL, `last_seen_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `revoked_at` DATETIME(3) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), KEY `user_devices_org_id_user_id_revoked_at_idx` (`org_id`,`user_id`,`revoked_at`), CONSTRAINT `user_devices_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `user_devices_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `security_events` (`id` CHAR(36) NOT NULL, `org_id` CHAR(36) NOT NULL, `user_id` CHAR(36) NULL, `severity` ENUM('INFO','WARNING','CRITICAL') NOT NULL, `event_type` VARCHAR(191) NOT NULL, `resource_type` VARCHAR(191) NULL, `resource_id` CHAR(36) NULL, `ip_address` VARCHAR(191) NULL, `metadata` JSON NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), KEY `security_events_org_id_created_at_idx` (`org_id`,`created_at`), KEY `security_events_org_id_severity_created_at_idx` (`org_id`,`severity`,`created_at`), CONSTRAINT `security_events_org_id_fkey` FOREIGN KEY (`org_id`) REFERENCES `organizations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `security_events_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE SET NULL ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
